import {TOPICS,PHASES,QUESTION_BANK,CARDS,parseBase,convert,conversionSteps,sumSteps,equalAnswer,mastery,level,formatTime,diagnosticQuestions,examQuestions,similarQuestion} from './core.js';
import {LESSONS,PAGE_MAP,ERRATA} from './content.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='impulso-informatica-v1';
const fresh=()=>({version:1,route:'inicio',elapsed:0,running:false,lastTick:Date.now(),attempts:[],done:[],diagnostic:null,quiz:null,exam:null,cardSchedule:{},cardId:null,cardFlip:false,cardReviews:0,lesson:'base',practiceTopic:'mix',solver:{value:'47',from:10,to:2,steps:0},sourcePage:1,showReset:false});
let state=fresh(),storageOK=true;try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&Array.isArray(saved.attempts)&&Array.isArray(saved.done)){state={...state,...saved};state.elapsed=Math.max(0,Math.min(7200,Number(state.elapsed)||0));}}catch{storageOK=false;}
let toastTimer,confirmExam=false,solverError='',asciiResult=null;
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',book:'<path d="M12 5v16M3 3c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',chart:'<path d="M4 20h17M7 16v-5m5 5V5m5 11V8"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',flash:'<path d="m13 2-9 12h7l-1 8 10-13h-7Z"/>',cards:'<rect x="6" y="7" width="14" height="14" rx="2"/><path d="M16 3H4a1 1 0 0 0-1 1v12"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',repeat:'<path d="M4 10a8 8 0 0 1 14-5l2 2m0-5v5h-5M20 14a8 8 0 0 1-14 5l-2-2m0 5v-5h5"/>',save:'<path d="M5 3h12l4 4v14H3V3Z"/><path d="M7 3v6h10V3M7 21v-8h10v8"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v1"/>'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}}
function toast(text){const el=$('#toast');if(!el)return;el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function cite(page){return `<button class="cite" data-action="source" data-page="${page}" title="Consultar la página fuente">${icon('book')} PDF p. ${page} <span>· impresa p. ${page+39}</span></button>`;}
function startClock(){if(state.elapsed>=7200)return;state.running=true;state.lastTick=Date.now();save();}
function phaseNow(){const m=state.elapsed/60;return PHASES.find(p=>m<Number(p.time.split('–')[1]))||PHASES[5];}
function mark(id){if(!state.done.includes(id))state.done.push(id);save();}
function overall(){return state.attempts.length?Math.round(state.attempts.filter(a=>a.ok).length/state.attempts.length*100):null;}
function unresolved(){const map=new Map();state.attempts.forEach(a=>{if(a.ok)map.delete(a.qid);else map.set(a.qid,a);});return [...map.values()];}
function weakest(){return Object.keys(TOPICS).sort((a,b)=>(mastery(state.attempts,a)??-1)-(mastery(state.attempts,b)??-1));}
function header(){return `<header class="topbar"><div class="breadcrumb">Tu espacio de estudio <span>/</span> <strong>Informática</strong></div><div class="top-right"><div class="global-clock">${icon('clock')}<strong id="global-study-time">${formatTime(7200-state.elapsed)}</strong><button data-action="toggle-clock" id="global-toggle" aria-label="${state.running?'Pausar':'Reanudar'} sesión">${state.running?'Ⅱ':'▶'}</button></div><span class="autosave">${icon('check')} ${storageOK?'Progreso guardado':'Guardado no disponible'}</span><div class="avatar" aria-label="Estudiante">TÚ</div></div></header>`;}
function sidebar(){const links=[['inicio','home','Mi sesión'],['diagnostico','target','Diagnóstico'],['fundamentos','book','Fundamentos'],['procedimientos','flash','Procedimientos'],['tarjetas','cards','Memoria activa'],['simulacro','clock','Simulacro'],['repaso','chart','Resultados y repaso'],['fuentes','book','Material y fuentes']];return `<aside class="sidebar"><a class="brand" href="#inicio" aria-label="Impulso, inicio"><span class="brandmark">ıı<span>${icon('arrow')}</span></span><span>impulso<span class="brand-dot">.</span><small>APRENDE. PRACTICA. DOMINA.</small></span></a><div class="course-label">TU RUTA DE APRENDIZAJE</div><nav aria-label="Navegación principal">${links.map(([id,ic,label])=>`<button data-route="${id}" class="nav-item ${state.route===id?'active':''}" ${state.route===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${state.done.includes(id)?'<span class="nav-check">✓</span>':''}${id==='simulacro'?'<small>25</small>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="focus-note"><span class="tiny-star">✧</span><strong>Un objetivo. Dos horas.</strong><p>Cada ejercicio es un paso más cerca de dominar tu examen.</p><div class="mini-line"><span style="width:${Math.round(state.elapsed/7200*100)}%"></span></div><small>${Math.floor(state.elapsed/60)} de 120 minutos de estudio</small></div><button class="nav-item ${state.route==='fuentes'?'active':''}" data-route="fuentes">${icon('book')}<span>Tu material de estudio</span><small>17 p.</small></button><div class="sidebar-caption">Inspiración académica UNAM<br>Herramienta independiente de estudio</div></div></aside>`;}
function clockPanel(){return `<div class="session-clock"><div class="clock-label"><span class="live-dot ${state.running?'running':''}"></span> TU TIEMPO DE ESTUDIO</div><div class="clock-row"><strong id="study-time">${formatTime(7200-state.elapsed)}</strong><button class="clock-control" data-action="toggle-clock" aria-label="${state.running?'Pausar':'Reanudar'} cronómetro" id="clock-toggle">${state.running?'Ⅱ':'▶'}</button></div><div class="mini-line light"><span id="time-progress" style="width:${state.elapsed/72}%"></span></div><div class="clock-foot"><span id="clock-status">${state.running?'Sesión en marcha':'A tu ritmo · en pausa'}</span><span>120 min</span></div></div>`;}
function shell(){return `${sidebar()}<div class="workspace">${header()}<main id="main" tabindex="-1">${!storageOK?'<div class="notice">El navegador no permite guardar el progreso. Mantén esta pestaña abierta o permite el almacenamiento local.</div>':''}${state.elapsed>=7200?'<div class="notice">Terminaste los 120 minutos. Puedes seguir repasando tus errores sin cronómetro.</div>':''}${view()}</main><footer>Hecho para practicar con intención. <span>Basado en tus 17 páginas de Informática.</span></footer></div><div id="toast" role="status" aria-live="polite"></div>${resetDialog()}`;}
function pageTitle(kicker,title,desc,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`;}
function progressStats(){const vals=[['clock',Math.floor(state.elapsed/60)+'<small> / 120 min</small>','Tiempo dedicado'],['check',state.attempts.filter(a=>a.ok).length,'Respuestas correctas'],['chart',overall()===null?'—':overall()+'<small>%</small>','Aciertos en tu práctica'],['book',state.done.length+'<small> / 6</small>','Bloques completados']];return `<div class="stats-grid">${vals.map(([ic,value,label])=>`<div class="stat"><span class="stat-icon">${icon(ic)}</span><div><strong>${value}</strong><span>${label}</span></div></div>`).join('')}</div>`;}
function dashboard(){const resume=state.diagnostic?'procedimientos':'diagnostico';return `${pageTitle('TU PLAN INTENSIVO','Dos horas. Un gran avance.','Domina lo esencial de Informática, un ejercicio a la vez.','<span class="pill outline">'+icon('book')+' Bachillerato · 17 páginas</span>')}<section class="hero"><div class="hero-copy"><span class="hero-tag"><span></span> ESTUDIA CON ESTRATEGIA</span><h2>No memorices todo.<br><em>Aprende a resolver.</em></h2><p>Una ruta de 120 minutos que se adapta a ti.<br>Detecta tus puntos débiles, practica y llega con confianza.</p><button class="button gold" data-action="begin">${state.diagnostic?'Continuar mi sesión':'Comenzar diagnóstico'} ${icon('arrow')}</button><div class="hero-meta">${icon('check')} Sin registro <span>·</span> Progreso automático <span>·</span> A tu ritmo</div></div><div class="binary-art" aria-label="Ejemplo visual: 13 decimal equivale a 1101 binario"><div class="art-top"><span>EL MISMO VALOR. OTRA BASE.</span><span>${icon('arrow')}</span></div><div class="decimal-art">13<small>DECIMAL</small></div><div class="art-arrow">↓ <span>convierte · comprende</span></div><div class="bit-art">${[1,1,0,1].map((x,i)=>`<div class="${x?'lit':''}"><strong>${x}</strong><small>${[8,4,2,1][i]}</small></div>`).join('')}</div><div class="art-bottom">8 + 4 + 0 + 1 <span>= 13</span></div><div class="art-caption">Basado en la tabla de tu material · p. 6</div></div></section>${progressStats()}<div class="dashboard-columns"><section><div class="section-heading"><div><span class="eyebrow">PASO A PASO</span><h2>Tu ruta de 120 minutos</h2></div><span class="muted small">6 bloques · tú marcas el ritmo</span></div><div class="route-list">${PHASES.map((p,i)=>`<button class="route-card ${state.done.includes(p.id)?'completed':''} ${p.id===phaseNow().id?'current':''}" data-route="${p.id}"><span class="phase-number">${state.done.includes(p.id)?'✓':String(i+1).padStart(2,'0')}</span><div class="phase-copy"><div><strong>${p.name}</strong>${i===0&&!state.diagnostic?'<span class="tag start-tag">EMPIEZA AQUÍ</span>':''}${state.done.includes(p.id)?'<span class="tag">COMPLETADO</span>':''}</div><p>${p.desc}</p></div><div class="phase-time"><strong>${p.minutes} min</strong><small>min ${p.time}</small></div>${icon('arrow')}</button>`).join('')}</div></section><aside class="right-column">${clockPanel()}<section class="panel tip-panel"><span class="tip-icon">${icon('flash')}</span><div class="eyebrow">TU MEJOR ESTRATEGIA</div><h3>Practica más.<br>Relee menos.</h3><p>Intenta resolver antes de ver la explicación. Equivocarte ahora te dice exactamente qué repasar.</p><div class="tip-divider"></div><strong>Prioridad de hoy</strong><div class="topic-chips"><span>Conversiones</span><span>Suma binaria</span><span>ASCII</span></div><button class="text-button" data-route="fuentes">Explorar el material ${icon('arrow')}</button></section><div class="source-note">${icon('info')}<p>La prioridad se estima por los resaltados y ejercicios del PDF. No predice las preguntas reales del examen.</p></div></aside></div>`;}
function quizIntro(){return `${pageTitle('BLOQUE 01 · MINUTOS 0–10','Primero, descubre tu punto de partida.','10 preguntas para enfocar tu tiempo donde más lo necesitas.')}<section class="panel intro-panel"><div class="big-symbol">${icon('target')}</div><h2>Tu mapa antes de empezar</h2><p>Combina conceptos, conversiones y unidades. Intenta cada respuesta sin consultar el material.</p><div class="intro-facts"><span><strong>10</strong>preguntas iniciales</span><span><strong>6</strong>áreas de aprendizaje</span><span><strong>10 min</strong>tiempo sugerido</span></div><p class="muted small">Si fallas, recibirás una corrección y un ejercicio similar antes de avanzar. Los refuerzos no alteran tu calificación inicial.</p><button class="button primary" data-action="start-diagnostic">Empezar diagnóstico ${icon('arrow')}</button></section>`;}
function diagnosticView(){if(state.quiz?.mode==='diagnostic')return quizView();if(!state.diagnostic)return quizIntro();const d=state.diagnostic;return `${pageTitle('DIAGNÓSTICO COMPLETADO','Ya tienes tu punto de partida.','Tu práctica se ajustará a los resultados de cada tema.')}<div class="result-banner"><div class="score-circle">${d.correct}<small>/ 10</small></div><div><h2>${d.correct>=8?'Una buena base para profundizar.':'Ya sabemos dónde enfocar la práctica.'}</h2><p>Resultado inicial: ${d.correct*10}%. Los refuerzos y tu práctica posterior se registran por separado.</p><button class="button gold" data-route="fundamentos">Estudiar fundamentos ${icon('arrow')}</button></div></div>${topicBars(d.attempts)}<div class="actions"><button class="button secondary" data-action="start-diagnostic">Repetir diagnóstico</button><button class="text-button" data-action="retry-errors">Practicar mis errores ${icon('arrow')}</button></div>`;}
function topicBars(attempts=state.attempts){return `<section class="panel"><div class="section-heading"><h2>Dominio por tema</h2><span class="small muted">Aciertos en los últimos 12 intentos por tema</span></div><div class="mastery-grid">${Object.entries(TOPICS).map(([id,label])=>{const m=mastery(attempts,id),n=attempts.filter(a=>a.topic===id).length;return `<div class="mastery-item"><div><strong>${label}</strong><span>${m===null?'Sin evaluar':m+'%'}</span></div><div class="mastery-track"><span class="${m!==null&&m<60?'weak':''}" style="width:${m||0}%"></span></div><small>${n} intento${n!==1?'s':''}${m===null?' · necesita diagnóstico':m<60?' · prioridad de repaso':m>=80?' · sigue consolidando':' · en progreso'}</small></div>`;}).join('')}</div></section>`;}
function lessonView(){const l=LESSONS.find(l=>l.topic===state.lesson)||LESSONS[0];return `${pageTitle('BLOQUE 02 · MINUTOS 10–35','Una regla clara. Una respuesta correcta.','Lee lo esencial, prueba un ejemplo y comprueba que puedes resolverlo.')}<div class="lesson-tabs" role="group" aria-label="Temas de fundamentos">${LESSONS.map(x=>`<button data-action="lesson" data-topic="${x.topic}" class="${l.topic===x.topic?'selected':''}">${TOPICS[x.topic]}</button>`).join('')}</div><div class="lesson-layout"><article class="panel lesson"><div class="section-heading"><span class="pill">${l.tag}</span>${cite(l.pages[0])}</div><h2>${l.title}</h2><p class="lead">${l.summary}</p><ol class="rule-list">${l.rules.map(r=>`<li>${r}</li>`).join('')}</ol>${l.topic==='base'?binaryLab():l.topic==='units'?unitLadder():l.topic==='ascii'?asciiLab():''}<h3>Ejemplos resueltos</h3>${l.examples.map(([a,b,p])=>`<div class="worked-example"><strong>${a}</strong><p>${b}</p><small>${p}</small></div>`).join('')}${l.extras.map(([a,b])=>`<details><summary>${a}</summary><p>${b}</p></details>`).join('')}<div class="lesson-citations">Fuentes: ${l.pages.map(p=>cite(p)).join('')}</div><div class="actions"><button class="button primary" data-action="quick" data-topic="${l.topic}">Comprobar lo aprendido ${icon('arrow')}</button></div></article><aside><section class="panel priority-panel"><span class="eyebrow">DÓNDE PONER ATENCIÓN</span><h3>Prioridad ${l.priority.toLowerCase()}</h3><p>${l.reason}</p><dl><dt>Dificultad</dt><dd>${l.difficulty}</dd><dt>Presencia estimada</dt><dd>${l.priority}</dd></dl><p class="small muted">Estimación cualitativa por énfasis y ejercicios; no es una predicción del examen.</p></section><section class="panel"><h3>Recuerda sin mirar</h3><p>Cierra la explicación y di en voz alta cómo resolverías el ejemplo. Después compruébalo.</p><button class="text-button" data-route="tarjetas">Practicar tarjetas ${icon('arrow')}</button></section><button class="button secondary full" data-action="complete-foundations">Completar bloque ${icon('check')}</button><p class="small muted">Requiere un acierto en sistemas, unidades y ASCII. Puedes estudiar los temas en el orden que necesites.</p></aside></div>`;}
function binaryLab(){return `<div class="binary-lab"><div class="section-heading"><h3>Construye un número</h3><span class="tag">TOCA LOS BITS</span></div><div class="lab-bits">${[8,4,2,1].map((v,i)=>`<button class="${[0,1,3].includes(i)?'on':''}" data-action="bit" data-value="${v}" aria-pressed="${[0,1,3].includes(i)}"><small>2<sup>${3-i}</sup> = ${v}</small><strong>${[0,1,3].includes(i)?1:0}</strong></button>`).join('')}</div><p id="binary-output">1101₂ = 8 + 4 + 1 = <strong>13 decimal</strong></p><small>Tabla posicional · PDF 2 y 6</small></div>`;}
function unitLadder(){return `<div class="unit-ladder">${['bit','byte','KB','MB','GB','TB','PB'].map((u,i)=>`<span><strong>${u}</strong>${i?'<small>× '+(i===1?'8':'1024')+' del anterior</small>':''}</span>`).join('')}</div>`;}
function asciiLab(){return `<form id="ascii-form" class="lab-form"><h3>Codifica tu grupo</h3><label for="ascii-input">Texto (caracteres ASCII 32–126, máximo 24)</label><div class="input-row"><input id="ascii-input" name="ascii" maxlength="24" placeholder="Ej. 405" value="405" required><button class="button secondary" type="submit">Codificar</button></div><div id="ascii-output" class="ascii-output" aria-live="polite">${asciiResult||'Escribe tu grupo y compara sus códigos decimal y hexadecimal.'}</div><small>Procedimiento de las páginas 16–17 del PDF.</small></form>`;}
function solverView(){const s=state.solver;let result=null;try{result=conversionSteps(s.value,s.from,s.to);}catch{}return `<section class="panel solver"><div class="section-heading"><div><span class="eyebrow">LABORATORIO PASO A PASO</span><h2>Entiende cada conversión</h2></div><span class="pill">${icon('flash')} Con guía</span></div><form id="solver-form"><div class="solver-fields"><label>Número<input name="value" value="${esc(s.value)}" maxlength="32" required placeholder="Ej. 47"></label><label>Base de origen<select name="from">${baseOptions(s.from)}</select></label><span class="solver-arrow">→</span><label>Base de destino<select name="to">${baseOptions(s.to)}</select></label><button class="button primary" type="submit">Resolver</button></div></form>${solverError?`<p role="alert" class="error-text">${esc(solverError)}</p>`:''}${result&&s.steps>0?`<div class="solver-result"><div class="solver-answer">${esc(s.value)}<sub>${s.from}</sub><span> = </span>${result.out}<sub>${s.to}</sub></div><ol class="step-list">${result.steps.slice(0,s.steps).map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${s.steps<result.steps.length?'<button class="button secondary" data-action="next-step">Ver siguiente paso →</button>':'<span class="success-text">✓ Procedimiento completo. Ahora inténtalo sin ayuda.</span>'}</div>`:'<p class="small muted solver-help">Elige una conversión. Revela el procedimiento un paso a la vez.</p>'}<div class="lesson-citations">${cite(7)}${cite(8)}${cite(9)}</div></section>`;}
function baseOptions(selected){return [[2,'Binario · 2'],[8,'Octal · 8'],[10,'Decimal · 10'],[16,'Hexadecimal · 16']].map(([v,l])=>`<option value="${v}" ${Number(selected)===v?'selected':''}>${l}</option>`).join('');}
function practiceView(){if(state.quiz&&['practice','quick','errors'].includes(state.quiz.mode))return quizView();const weak=weakest()[0];return `${pageTitle('BLOQUE 03 · MINUTOS 35–70','El procedimiento se aprende practicando.','Conversiones intercaladas, suma con acarreo y retroalimentación inmediata.')}<div class="notice subtle">${icon('target')} ${state.attempts.length?`Tu siguiente foco sugerido: <strong>${TOPICS[weak]}</strong>.`:'Empieza con el nivel básico; la dificultad subirá con tus aciertos.'} No se avanza automáticamente: tú confirmas cada paso.</div>${solverView()}<div class="practice-grid"><section class="panel"><span class="eyebrow">PRÁCTICA ADAPTATIVA</span><h2>Ahora, resuélvelo tú</h2><p>Un error baja la dificultad y activa un ejercicio similar. Dos o más aciertos recientes te preparan para retos mayores.</p><label class="field-label" for="practice-topic">¿Qué quieres practicar?</label><select id="practice-topic">${[['mix','Intercalar mis temas débiles'],...Object.entries(TOPICS)].map(([id,label])=>`<option value="${id}" ${state.practiceTopic===id?'selected':''}>${label}</option>`).join('')}</select><button class="button primary full" data-action="start-practice">Empezar práctica ${icon('arrow')}</button><button class="text-button" data-action="retry-errors">${icon('repeat')} Repetir ejercicios incorrectos (${unresolved().length})</button></section><section class="panel"><span class="eyebrow">SUMA BINARIA GUIADA</span><h3>No pierdas el acarreo</h3><form id="sum-form"><label for="sum-input">Sumandos separados por +</label><div class="input-row"><input id="sum-input" name="values" value="10011 + 11110 + 11011" required><button class="button secondary" type="submit">Ver pasos</button></div></form><div id="sum-result" aria-live="polite"><div class="sum-mini"><span>1 + 1 = <strong>10₂</strong></span><small>Escribe 0 · lleva 1</small></div><p class="small muted">Intenta primero en papel. Compara después columna a columna.</p></div>${cite(10)}${cite(13)}</section></div><button class="button secondary" data-action="complete-procedures">Completar bloque ${icon('check')}</button><p class="small muted">Requiere al menos un acierto en conversiones, agrupación y suma. Los refuerzos también cuentan.</p>`;}
function activeQ(){const q=state.quiz;return q.remedial||q.questions[q.index];}
function answersHTML(q,value,disabled=false){if(q.type==='num')return `<label class="answer-label" for="answer">Tu respuesta <span>· base ${q.base||10}, sin subíndice</span></label><input id="answer" class="numeric-answer" name="answer" type="text" inputmode="${(q.base||10)===16?'text':'numeric'}" autocomplete="off" spellcheck="false" placeholder="Escribe tu resultado" value="${esc(value||'')}" ${disabled?'disabled':''} required>`;return `<div class="options" role="group" aria-label="Opciones de respuesta">${q.options.map((o,i)=>`<button type="button" class="option ${value===o?'chosen':''}" data-action="select-answer" data-index="${i}" aria-pressed="${value===o}" ${disabled?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${esc(o)}<span class="option-dot"></span></button>`).join('')}</div>`;}
function quizView(){const z=state.quiz,q=activeQ(),feedback=z.remedial?z.remedyFeedback:z.feedback,answer=z.remedial?z.remedyAnswer:z.answer;const title=z.mode==='diagnostic'?'Conoce tu punto de partida':z.mode==='errors'?'Convierte tus errores en aciertos':z.mode==='quick'?'Comprueba lo aprendido':'Un ejercicio. Toda tu atención.';const count=z.mode==='practice'?`Nivel ${level(state.attempts,q.topic)} de 3`:`Pregunta ${z.index+1} de ${z.questions.length}`;return `${pageTitle(z.mode==='diagnostic'?'BLOQUE 01 · DIAGNÓSTICO':'RECUPERACIÓN ACTIVA',title,'Intenta resolver sin ayuda. El procedimiento aparece después de responder.')}<div class="quiz-layout"><section class="panel question-panel"><div class="question-top"><span class="pill">${TOPICS[q.topic]}</span><span class="muted small">${count}</span></div>${z.mode!=='practice'?`<div class="question-progress"><span style="width:${z.index/z.questions.length*100}%"></span></div>`:''}${z.remedial?'<div class="remedial-label">↻ Refuerzo del mismo tema · responde bien para continuar</div>':''}<h2>${esc(q.prompt)}</h2><form id="answer-form">${answersHTML(q,answer,!!feedback)}${!feedback?`<div class="actions"><button class="button primary" type="submit">Comprobar respuesta ${icon('check')}</button><button class="text-button" type="button" data-action="hint">Necesito una pista</button></div><p id="answer-notice" class="error-text" role="alert"></p>`:''}</form><div id="hint-output"></div>${feedback?feedbackHTML(q,feedback):''}${feedback?`<div class="actions">${feedback.ok?`<button class="button primary" data-action="next-question">${z.remedial?'Continuar después del refuerzo':z.mode==='practice'?'Siguiente ejercicio':z.index===z.questions.length-1?'Ver mis resultados':'Siguiente pregunta'} ${icon('arrow')}</button>`:`<button class="button primary" data-action="remedy">Resolver un ejercicio similar ${icon('repeat')}</button>`}</div>`:''}${z.mode!=='diagnostic'?'<button class="text-button" data-action="end-practice">Terminar esta práctica y elegir otro tema</button>':''}<div class="question-source">${cite(q.page)}<span>Ejercicio ${q.kind?'basado en el procedimiento del material':'del contenido del material'}</span></div></section><aside><section class="panel"><span class="eyebrow">TU PRÁCTICA, A TU MEDIDA</span><h3>${z.remedial?'Primero, afianza la regla.':'Comprender antes de avanzar.'}</h3><p>${z.remedial?'Este refuerzo trabaja la misma habilidad. Si vuelves a fallar, tendrás otra explicación y otra oportunidad.':'Escribe los pasos en papel. La respuesta correcta importa, pero saber repetir el procedimiento importa más.'}</p><div class="practice-count"><strong>${state.attempts.filter(a=>a.ok).length}</strong><span>aciertos acumulados</span></div><button class="text-button" data-action="leave-quiz">Guardar y volver</button></section>${clockPanel()}</aside></div>`;}
function feedbackHTML(q,f){return `<div class="feedback ${f.ok?'correct':'incorrect'}" role="status"><strong>${f.ok?'✓ Correcto. Sigue así.':'↳ Vamos a corregirlo.'}</strong>${!f.ok?`<p>Tu respuesta: <b>${esc(f.answer)}</b>. Resultado correcto: <b>${esc(q.answer)}${q.type==='num'?' (base '+(q.base||10)+')':''}</b>.</p><p>${errorReason(q,f.answer)}</p>`:''}<ol class="feedback-steps">${q.explanation.split('\n').map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${!f.ok?'<p class="small">Ahora comprueba el aprendizaje con un ejercicio similar.</p>':''}</div>`;}
function errorReason(q,a){if(q.kind==='convert'){const{from,to}=q.params;return from===10?`Revisa los residuos y su orden: la lectura va del último al primero. La respuesta debe estar en base ${to}.`:[8,16].includes(to)&&from===2?`Revisa el tamaño de los grupos (${to===8?3:4} bits), empezando por la derecha.`:'Revisa la posición 0 a la derecha y los valores de cada dígito; no elimines ceros internos.';}if(q.topic==='sum')return 'Revisa cada columna de derecha a izquierda. Incluye el acarreo que recibes y no olvides el acarreo final.';if(q.topic==='units')return 'Distingue bits de bytes y revisa la dirección del cambio: 8 bits por byte; factor 1024 entre las unidades de la tabla.';if(q.topic==='ascii')return 'Revisa si se pide cantidad de símbolos, número de bits o el código de un carácter. Son valores diferentes.';return 'Contrasta tu respuesta con la base y la regla posicional. Un valor escrito con los mismos dígitos puede cambiar según su base.';}
function choosePractice(topic=state.practiceTopic){if(topic==='mix'){const sorted=weakest();const weak=sorted.slice(0,3);const last=state.attempts.at(-1)?.topic;topic=weak.find(t=>t!==last)||weak[0];}const lv=level(state.attempts,topic),recent=state.attempts.slice(-8).map(a=>a.qid);let pool=QUESTION_BANK.filter(q=>q.topic===topic&&q.difficulty<=lv&&!recent.includes(q.id));if(!pool.length)pool=QUESTION_BANK.filter(q=>q.topic===topic&&q.difficulty<=lv);return pool[Math.floor(Math.random()*pool.length)];}
function beginQuiz(mode,questions){state.quiz={mode,questions,index:0,answer:'',feedback:null,remedial:null,remedyAnswer:'',remedyFeedback:null,baseline:[]};state.route=mode==='diagnostic'?'diagnostico':'procedimientos';startClock();render();}
function logAttempt(q,answer,mode){const a={qid:q.id,question:q,topic:q.topic,answer,ok:equalAnswer(q,answer),at:Date.now(),mode};state.attempts.push(a);if(state.attempts.length>4000)state.attempts=state.attempts.slice(-4000);save();return a;}
function checkAnswer(answer){const z=state.quiz,q=activeQ();if(!answer||!String(answer).trim()){const n=$('#answer-notice');if(n)n.textContent='Elige una opción o escribe un resultado antes de comprobar.';return;}if((z.remedial?z.remedyFeedback:z.feedback))return;const a=logAttempt(q,answer,z.remedial?'refuerzo':z.mode);if(z.remedial){z.remedyAnswer=answer;z.remedyFeedback=a;}else{z.answer=answer;z.feedback=a;if(z.mode==='diagnostic')z.baseline.push(a);}render();}
function nextQuestion(){const z=state.quiz;if(!(z.remedial?z.remedyFeedback:z.feedback)?.ok)return;if(z.remedial){z.remedial=null;z.remedyFeedback=null;z.remedyAnswer='';}z.index++;if(z.mode==='practice'){z.questions.push(choosePractice());}if(z.index>=z.questions.length){const mode=z.mode;if(mode==='diagnostic'){state.diagnostic={correct:z.baseline.filter(a=>a.ok).length,attempts:z.baseline,at:Date.now()};mark('diagnostico');state.route='diagnostico';}else{state.route='procedimientos';}state.quiz=null;render();if(mode!=='diagnostic')toast('Práctica completada. Tus resultados ya están guardados.');return;}z.answer='';z.feedback=null;render();}
function flashView(){if(!state.cardId)pickCard();const card=CARDS.find(c=>c.id===state.cardId)||CARDS[0];const now=Date.now(),due=CARDS.filter(c=>!state.cardSchedule[c.id]||state.cardSchedule[c.id].due<=now).length;return `${pageTitle('BLOQUE 04 · MINUTOS 70–90','Recuerda primero. Comprueba después.','Las tarjetas difíciles regresan antes; las dominadas esperan más.')}<div class="flash-layout"><section><div class="flash-meta"><span class="pill">${TOPICS[card.topic]}</span><span>${due} tarjetas pendientes · ${state.cardReviews} repasos</span></div><button class="flashcard ${state.cardFlip?'flipped':''}" data-action="flip-card" aria-label="${state.cardFlip?'Ver pregunta':'Revelar respuesta'}"><span class="flash-kicker">${state.cardFlip?'COMPRUEBA TU RESPUESTA':'PIENSA SIN MIRAR'}</span><span class="flash-question">${esc(state.cardFlip?card.back:card.front)}</span><span class="flash-instruction">${icon('repeat')} ${state.cardFlip?'Toca para volver a la pregunta':'Toca la tarjeta para revelar'}</span></button><div class="flash-source">${cite(card.page)}</div>${state.cardFlip?`<div class="flash-ratings"><button class="button danger-outline" data-action="rate-card" data-rating="again">No lo recordé<small>Repetir en 30 s</small></button><button class="button secondary" data-action="rate-card" data-rating="hard">Con dificultad<small>Repetir en 3 min</small></button><button class="button primary" data-action="rate-card" data-rating="good">Lo sabía<small>Repetir en 7 min</small></button></div>`:'<p class="center muted">Intenta responder en voz alta antes de dar vuelta.</p>'}<div class="actions"><button class="text-button" data-action="weak-cards">Priorizar mis temas débiles ${icon('arrow')}</button><button class="text-button" data-action="complete-cards">Completar bloque</button></div></section><aside><section class="panel"><span class="eyebrow">REPETICIÓN ESPACIADA</span><h3>Menos vueltas.<br>Más recuperación.</h3><p>Las tarjetas nuevas y vencidas van primero. Los temas con errores tienen prioridad.</p><div class="card-rule"><span>↻</span><p><strong>No lo recordé</strong><small>Vuelve pronto. Explica la regla con tus palabras.</small></p></div><div class="card-rule"><span>✓</span><p><strong>Lo sabía</strong><small>Deja pasar tiempo antes de recuperarlo otra vez.</small></p></div><p class="small muted">Si no hay tarjetas vencidas, puedes adelantar la siguiente. El intervalo usa el reloj del navegador.</p></section>${clockPanel()}</aside></div>`;}
function pickCard(weakOnly=false){const now=Date.now(),weak=weakest(),current=state.cardId;let pool=CARDS.filter(c=>!state.cardSchedule[c.id]||state.cardSchedule[c.id].due<=now);if(weakOnly){const filtered=pool.filter(c=>weak.slice(0,2).includes(c.topic));if(filtered.length)pool=filtered;}if(!pool.length)pool=[...CARDS].sort((a,b)=>(state.cardSchedule[a.id]?.due||0)-(state.cardSchedule[b.id]?.due||0));pool.sort((a,b)=>weak.indexOf(a.topic)-weak.indexOf(b.topic));const c=pool.find(c=>c.id!==current)||pool[0];state.cardId=c.id;state.cardFlip=false;save();}
function examView(){const e=state.exam;if(e?.submitted)return examResults();if(!e)return `${pageTitle('BLOQUE 05 · MINUTOS 90–110','Ahora, como si fuera el examen.','25 preguntas · 20 minutos · resultados al terminar.')}<section class="panel intro-panel"><div class="big-symbol">${icon('clock')}</div><h2>Demuestra lo que puedes resolver</h2><p>Opción múltiple, verdadero/falso y problemas numéricos, basados en los ejercicios y procedimientos de tu PDF.</p><div class="intro-facts"><span><strong>25</strong>preguntas</span><span><strong>20 min</strong>cronómetro</span><span><strong>0–10</strong>calificación</span></div><ul class="exam-rules"><li>Puedes volver a cualquier pregunta y cambiar tu respuesta.</li><li>No se mostrarán soluciones hasta entregar o agotar el tiempo.</li><li>El botón de pausa detiene ambos cronómetros.</li><li>Las preguntas sin respuesta cuentan como incorrectas.</li></ul><button class="button primary" data-action="start-exam">Iniciar simulacro ${icon('arrow')}</button></section>`;const q=e.questions[e.index],ans=e.answers[e.index],answered=Object.values(e.answers).filter(a=>String(a).trim()).length;return `${pageTitle('SIMULACRO EN CURSO','Confía en tu procedimiento.','No hay pistas ni correcciones hasta que termines.',`<div class="exam-clock"><span>${icon('clock')} Tiempo restante</span><strong id="exam-time">${formatTime(e.remaining)}</strong><button class="text-button" data-action="toggle-clock">${state.running?'Pausar':'Reanudar'}</button></div>`)}<div class="quiz-layout"><section class="panel question-panel"><div class="question-top"><span class="pill">${q.type==='num'?'Problema numérico':q.type==='tf'?'Verdadero / falso':'Opción múltiple'}</span><span class="muted">Pregunta ${e.index+1} de 25</span></div><div class="question-progress"><span style="width:${answered/25*100}%"></span></div><h2>${esc(q.prompt)}</h2><form id="exam-answer-form">${answersHTML(q,ans)}${q.type==='num'?'<button type="submit" class="button secondary save-answer">Guardar respuesta</button>':''}<p id="exam-answer-status" role="status" class="small muted">${ans?'Respuesta guardada. Puedes cambiarla.':'Aún sin responder.'}</p></form><div class="exam-navigation"><button class="button secondary" data-action="exam-prev" ${e.index===0?'disabled':''}>← Anterior</button><button class="button primary" data-action="exam-next" ${e.index===24?'disabled':''}>Siguiente →</button></div></section><aside><section class="panel exam-map"><h3>Tu hoja de respuestas</h3><p><strong>${answered}</strong> de 25 respondidas</p><div class="question-grid">${e.questions.map((q,i)=>`<button data-action="exam-jump" data-index="${i}" class="${e.index===i?'current':''} ${e.answers[i]?'answered':''}" aria-label="Pregunta ${i+1}${e.answers[i]?', respondida':''}" ${e.index===i?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><div class="map-legend"><span>● Respondida</span><span>○ Pendiente</span></div><button class="button primary full" data-action="finish-exam">Entregar simulacro</button>${confirmExam?`<div class="finish-confirm" role="alert"><p>${25-answered} sin responder. ¿Entregar ahora? Se calificarán como incorrectas.</p><button class="button gold full" data-action="confirm-exam">Sí, entregar</button><button class="text-button" data-action="cancel-finish">Seguir resolviendo</button></div>`:''}</section><div class="source-note">${icon('save')}<p>Tus respuestas se guardan en este navegador. Puedes recargar y continuar.</p></div></aside></div>`;}
function saveExamInput(){if(state.exam&&!state.exam.submitted&&$('#answer')){state.exam.answers[state.exam.index]=$('#answer').value.trim();save();}}
function submitExam(){if(!state.exam||state.exam.submitted)return;saveExamInput();state.exam.submitted=true;state.exam.finishedAt=Date.now();state.exam.questions.forEach((q,i)=>logAttempt(q,state.exam.answers[i]||'','simulacro'));mark('simulacro');state.route='simulacro';confirmExam=false;save();render();}
function examResults(){const e=state.exam,correct=e.questions.filter((q,i)=>equalAnswer(q,e.answers[i])).length;return `${pageTitle('SIMULACRO COMPLETADO','Tu resultado, con un siguiente paso claro.','Revisa el procedimiento de cada error y compruébalo con un nuevo intento.')}<section class="result-banner"><div class="score-circle">${(correct/25*10).toFixed(1)}<small>/ 10</small></div><div><span class="eyebrow">CALIFICACIÓN DEL SIMULACRO</span><h2>${correct} de 25 respuestas correctas · ${correct*4}%</h2><p>Duración activa: ${formatTime(1200-e.remaining)}. ${correct>=20?'Buen avance: usa el tiempo restante para cerrar errores.':'Enfoca el tiempo restante en los procedimientos que fallaste.'}</p><button class="button gold" data-route="repaso">Ver mi repaso final ${icon('arrow')}</button></div></section>${topicBars(state.attempts.filter(a=>a.mode==='simulacro'&&a.at>=e.startedAt))}<section class="panel"><div class="section-heading"><h2>Corrección del simulacro</h2><span class="muted small">${25-correct} errores o preguntas sin responder</span></div>${e.questions.map((q,i)=>{const ok=equalAnswer(q,e.answers[i]);return `<details class="exam-correction ${ok?'correct-item':'wrong-item'}"><summary><span>${ok?'✓':'↳'} ${i+1}. ${esc(q.prompt)}</span><span class="tag">${ok?'Correcta':'Repasar'}</span></summary><p>Tu respuesta: <strong>${esc(e.answers[i]||'Sin responder')}</strong> · Correcta: <strong>${esc(q.answer)}</strong></p><p class="pre-line">${esc(q.explanation)}</p>${cite(q.page)}${!ok?`<button class="button secondary" data-action="exam-remedy" data-index="${i}">Resolver uno similar</button>`:''}</details>`;}).join('')}</section><div class="actions"><button class="button secondary" data-action="new-exam">Hacer otro simulacro</button><span class="small muted">Se reemplazará este resultado; tus intentos seguirán en las estadísticas.</span></div>`;}
function reviewView(){const errors=unresolved(),weak=weakest(),mins=Math.ceil((7200-state.elapsed)/60),e=state.exam;return `${pageTitle('BLOQUE 06 · MINUTOS 110–120','Quédate con lo que más importa.','Tus errores, las reglas esenciales y un plan para los minutos restantes.',`<button class="button secondary" data-action="print">${icon('book')} Imprimir hoja</button>`)}<div class="review-summary"><section class="panel"><span class="eyebrow">TU SESIÓN</span><h2>${overall()===null?'Comienza para medir tu avance':overall()+'% de aciertos'}</h2><p>${state.attempts.length} intentos · ${state.attempts.filter(a=>a.ok).length} correctos · ${state.attempts.filter(a=>!a.ok).length} incorrectos</p><p>${e?.submitted?'Simulacro: '+(e.questions.filter((q,i)=>equalAnswer(q,e.answers[i])).length/25*10).toFixed(1)+'/10.':'Simulacro todavía no completado.'}</p><button class="text-button" data-route="simulacro">${e?.submitted?'Ver calificación y correcciones':'Ir al simulacro'} ${icon('arrow')}</button></section><section class="panel recommendation"><span class="eyebrow">TE QUEDAN ${mins} MINUTOS</span><h3>${state.attempts.length?'Enfócate en '+TOPICS[weak[0]].toLowerCase()+'.':'Haz primero el diagnóstico.'}</h3><p>${state.attempts.length?(mins<=10?'Resuelve dos errores pendientes, recupera las reglas sin mirar y verifica un ejemplo.':'Alterna tus dos temas más débiles, después haz el simulacro y reserva 10 minutos para corregir.'):'Diez preguntas te ayudarán a decidir dónde invertir los siguientes minutos.'}</p><button class="button primary" data-action="retry-errors">${icon('repeat')} Practicar errores (${errors.length})</button></section></div>${topicBars()}<section class="panel"><div class="section-heading"><h2>Tu registro de errores</h2><span class="pill">${errors.length} pendientes</span></div>${errors.length?`<div class="error-frequency">${Object.entries(TOPICS).map(([id,name])=>{const n=state.attempts.filter(a=>a.topic===id&&!a.ok).length;return n?`<span>${name} <strong>${n} errores</strong></span>`:'';}).join('')}</div>${errors.slice(-12).reverse().map(a=>`<details><summary>${esc(a.question.prompt)}</summary><p>Tu respuesta: ${esc(a.answer||'Sin responder')} · Correcta: <strong>${esc(a.question.answer)}</strong></p><p class="pre-line">${esc(a.question.explanation)}</p>${cite(a.question.page)}<button class="button secondary" data-action="retry-one" data-id="${esc(a.qid)}">Repetir este ejercicio</button></details>`).join('')}`:'<p class="muted">'+(state.attempts.length?'No hay ejercicios pendientes de corregir. Sigue con práctica intercalada para comprobar retención.':'Todavía no hay intentos registrados. Tus errores aparecerán aquí con su corrección.')+'</p>'}</section><section class="panel print-sheet"><div class="section-heading"><div><span class="eyebrow">HOJA DE REPASO · INFORMÁTICA</span><h2>Reglas para llevar al examen</h2></div><span class="pill">Solo tu material</span></div><div class="cheatsheet-grid"><div><h3>01 · Bases y potencias</h3><p>Binario 2: 0–1 · Octal 8: 0–7 · Decimal 10: 0–9 · Hexadecimal 16: 0–9, A–F.</p><code>A=10 B=11 C=12 D=13 E=14 F=15</code><p>Valor = suma de (dígito × base^posición). Desde la derecha: posición 0.</p><small>PDF 2–6</small></div><div><h3>02 · Conversiones</h3><p>Decimal → base b: divisiones entre b; residuos de abajo hacia arriba.</p><p>Base b → decimal: multiplica por las potencias y suma.</p><code>125₈ = 1×64+2×8+5 = 85₁₀</code><small>PDF 7–8</small></div><div><h3>03 · Agrupación</h3><p>Octal: 3 bits. Hexadecimal: 4 bits. Agrupa desde la derecha y completa con ceros a la izquierda.</p><code>010|110|111₂ = 267₈<br>1100|0110₂ = C6₁₆</code><small>PDF 8–9</small></div><div><h3>04 · Suma y combinaciones</h3><p>1+1=10₂ · 1+1+1=11₂. Conserva el acarreo y trabaja desde la derecha.</p><p>n bits → 2ⁿ valores. Máximo sin signo: 2ⁿ−1.</p><code>1111₂+1111₂ = 11110₂</code><small>PDF 10–13</small></div><div><h3>05 · Almacenamiento</h3><p>1 byte = 8 bits. Bit: 0 o 1.</p><code>byte → KB → MB → GB → TB → PB</code><p>Según el PDF: cada salto ×1024 hacia unidades menores; ÷1024 hacia mayores.</p><small>PDF 15–17</small></div><div><h3>06 · ASCII</h3><p>Original: 1963, 7 bits, 128 símbolos. Extendido descrito: 8 bits, 256 símbolos.</p><code>A = 65₁₀ = 41₁₆<br>0 (carácter) = 48₁₀ = 30₁₆<br>Espacio = 32₁₀ = 20₁₆</code><small>PDF 15–17</small></div></div><div class="notice small">Cuidado con el material: 33₁₀=41₈; 29F₁₆+1=2A0₁₆; 10011₂+11110₂+11011₂=1001100₂. Ver erratas en las fuentes.</div></section><div class="actions"><button class="button primary" data-action="complete-review">Marcar repaso completado ${icon('check')}</button><button class="button secondary" data-action="export">Descargar mi progreso</button><button class="text-button danger" data-action="reset">Reiniciar sesión</button></div>`;}
function assetPDF(){return window.IMPULSO_ASSETS?.pdf||'public/informatica.pdf';}
function assetPage(p){return window.IMPULSO_ASSETS?.pages[p]||`public/pages/${p}.jpg`;}
function sourceView(){const p=state.sourcePage;return `${pageTitle('TU MATERIAL · 17 PÁGINAS','Todo vuelve a la fuente.','Análisis de las páginas 40–56 del material impreso. Cada explicación enlaza su página del PDF.',`<a class="button secondary" href="${assetPDF()}" download="informatica.pdf">Descargar PDF</a>`)}<section class="panel"><h2>Qué estudiar primero</h2><p class="muted">La presencia estimada es cualitativa: considera resaltados, tablas y ejercicios. No conocemos las preguntas reales de tu examen.</p><div class="table-wrap"><table><thead><tr><th>Tema</th><th>Dificultad</th><th>Importancia / presencia estimada</th><th>Motivo y páginas PDF</th></tr></thead><tbody>${LESSONS.map(l=>`<tr><td><strong>${TOPICS[l.topic]}</strong></td><td>${l.difficulty}</td><td><span class="tag">${l.priority}</span></td><td>${l.reason}<br><small>p. ${l.pages.join(', ')}</small></td></tr>`).join('')}</tbody></table></div></section><div class="source-layout"><section class="panel source-index"><h2>Mapa de las 17 páginas</h2>${PAGE_MAP.map(([title,desc],i)=>`<button class="source-row ${p===i+1?'selected':''}" data-action="page" data-page="${i+1}"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${title}</strong><p>${desc}</p><small>PDF ${i+1} · impresa ${i+40}</small></div></button>`).join('')}</section><section class="panel source-viewer"><div class="section-heading"><h3>PDF p. ${p} <span class="muted">· impresa ${p+39}</span></h3><div><button class="icon-button" data-action="page" data-page="${p-1}" ${p===1?'disabled':''} aria-label="Página anterior">←</button><button class="icon-button" data-action="page" data-page="${p+1}" ${p===17?'disabled':''} aria-label="Página siguiente">→</button></div></div><button class="zoom-source" data-action="zoom-page" title="Ampliar página"><img src="${assetPage(p)}" alt="Página ${p} del PDF: ${PAGE_MAP[p-1][0]}" class="source-image"></button><p class="small muted">Toca la imagen para ampliarla. Se corrigió la orientación de las últimas cuatro páginas para facilitar la lectura.</p></section></div><section class="panel"><div class="eyebrow">LECTURA CRÍTICA DEL MATERIAL</div><h2>Erratas y anotaciones que conviene corregir</h2><p>Se conservan los temas y la terminología del PDF. Las soluciones se comprueban con sus propios procedimientos; no se toma el resaltado como una clave de respuestas.</p>${ERRATA.map(e=>`<div class="erratum">${cite(e.page)}<p>${e.text}</p></div>`).join('')}</section>`;}
function resetDialog(){return state.showReset?`<div class="modal-backdrop"><section class="modal panel" role="dialog" aria-modal="true" aria-labelledby="reset-title"><h2 id="reset-title">¿Empezar de nuevo?</h2><p>Se borrarán de este navegador los intentos, las tarjetas y los cronómetros. Puedes descargar tu progreso antes de reiniciar.</p><div class="actions"><button class="button secondary" data-action="cancel-reset">Conservar progreso</button><button class="button primary" data-action="confirm-reset">Borrar y reiniciar</button></div></section></div>`:'';}
function view(){switch(state.route){case'inicio':return dashboard();case'diagnostico':return diagnosticView();case'fundamentos':return lessonView();case'procedimientos':return practiceView();case'tarjetas':return flashView();case'simulacro':return examView();case'repaso':return reviewView();case'fuentes':return sourceView();default:state.route='inicio';return dashboard();}}
function render(){save();$('#app').innerHTML=shell();}
function navigate(route){saveExamInput();state.route=route;confirmExam=false;render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
function handleAction(el){const a=el.dataset.action;switch(a){case'begin':if(state.diagnostic){startClock();navigate(state.quiz?(state.quiz.mode==='diagnostic'?'diagnostico':'procedimientos'):phaseNow().id==='diagnostico'?'fundamentos':phaseNow().id);}else if(state.quiz?.mode==='diagnostic'){startClock();navigate('diagnostico');}else beginQuiz('diagnostic',diagnosticQuestions());break;
 case'toggle-clock':tick();state.running=!state.running&&state.elapsed<7200;state.lastTick=Date.now();render();break;
 case'start-diagnostic':beginQuiz('diagnostic',diagnosticQuestions());break;
 case'source':state.sourcePage=Number(el.dataset.page);navigate('fuentes');break;
 case'zoom-page':{const wrap=document.createElement('div');wrap.className='modal-backdrop image-modal';wrap.innerHTML=`<button class="zoom-close" aria-label="Cerrar página ampliada">✕ Cerrar</button><img src="${assetPage(state.sourcePage)}" alt="Página ${state.sourcePage} ampliada">`;wrap.addEventListener('click',()=>wrap.remove());document.body.append(wrap);wrap.querySelector('button').focus();}break;
 case'page':if(Number(el.dataset.page)>=1&&Number(el.dataset.page)<=17){state.sourcePage=Number(el.dataset.page);render();$('.source-viewer')?.scrollIntoView({block:'start'});}break;
 case'lesson':state.lesson=el.dataset.topic;render();break;
 case'bit':el.classList.toggle('on');el.setAttribute('aria-pressed',String(el.classList.contains('on')));el.querySelector('strong').textContent=el.classList.contains('on')?'1':'0';{const bits=[...document.querySelectorAll('.lab-bits button')],vals=bits.filter(b=>b.classList.contains('on')).map(b=>Number(b.dataset.value));$('#binary-output').innerHTML=bits.map(b=>b.classList.contains('on')?'1':'0').join('')+'₂ = '+(vals.length?vals.join(' + '):0)+' = <strong>'+vals.reduce((a,b)=>a+b,0)+' decimal</strong>';}break;
 case'quick':beginQuiz('quick',[choosePractice(el.dataset.topic),choosePractice(el.dataset.topic),choosePractice(el.dataset.topic)]);break;
 case'complete-foundations':if(['base','units','ascii'].every(t=>state.attempts.some(a=>a.topic===t&&a.ok))){mark('fundamentos');navigate('procedimientos');toast('Fundamentos completados. Tú decides cuándo continuar.');}else toast('Comprueba un acierto en sistemas, unidades y ASCII antes de completar el bloque.');break;
 case'complete-procedures':if(['conv','group','sum'].every(t=>state.attempts.some(a=>a.topic===t&&a.ok))){mark('procedimientos');navigate('tarjetas');}else toast('Necesitas un acierto en conversiones, agrupación y suma. Practica cada procedimiento antes de avanzar.');break;
 case'next-step':state.solver.steps++;render();break;
 case'start-practice':state.practiceTopic=$('#practice-topic').value;beginQuiz('practice',[choosePractice()]);break;
 case'select-answer':if(state.route==='simulacro'&&state.exam&&!state.exam.submitted){saveExamInput();const e=state.exam;e.answers[e.index]=e.questions[e.index].options[Number(el.dataset.index)];render();}else if(state.quiz){const q=activeQ(),z=state.quiz;if(z.remedial)z.remedyAnswer=q.options[Number(el.dataset.index)];else z.answer=q.options[Number(el.dataset.index)];render();}break;
 case'hint':$('#hint-output').innerHTML=`<div class="notice subtle">${esc(activeQ().hint||'Revisa la regla del tema y distingue la base, el valor y el número de símbolos que pide el enunciado.')}</div>`;break;
 case'remedy':{const z=state.quiz;if(!(z.remedial?z.remedyFeedback:z.feedback)|| (z.remedial?z.remedyFeedback:z.feedback).ok)return;z.remedial=similarQuestion(activeQ());z.remedyAnswer='';z.remedyFeedback=null;render();}break;
 case'next-question':nextQuestion();break;
 case'leave-quiz':navigate('inicio');break;
 case'end-practice':state.quiz=null;navigate('procedimientos');break;
 case'retry-errors':{const errors=unresolved();if(!errors.length){toast('Sin errores pendientes. Comienza una práctica intercalada.');beginQuiz('practice',[choosePractice()]);}else beginQuiz('errors',errors.map(a=>a.question));}break;
 case'retry-one':{const q=unresolved().find(a=>a.qid===el.dataset.id)?.question;if(q)beginQuiz('errors',[q]);}break;
 case'flip-card':state.cardFlip=!state.cardFlip;render();break;
 case'rate-card':{const c=CARDS.find(c=>c.id===state.cardId),r=el.dataset.rating;state.cardSchedule[c.id]={due:Date.now()+({again:30000,hard:180000,good:420000}[r]),rating:r};state.cardReviews++;pickCard();render();toast(r==='again'?'Esta tarjeta volverá en 30 segundos.':r==='hard'?'La recuperarás de nuevo en 3 minutos.':'Buen trabajo. Volverá en 7 minutos.');}break;
 case'weak-cards':pickCard(true);render();break;
 case'complete-cards':if(state.cardReviews>=6){mark('tarjetas');navigate('simulacro');}else toast('Recupera al menos 6 tarjetas antes de completar este bloque.');break;
 case'start-exam':state.exam={questions:examQuestions(),answers:{},index:0,remaining:1200,submitted:false,startedAt:Date.now()};startClock();render();break;
 case'exam-prev':case'exam-next':case'exam-jump':saveExamInput();state.exam.index=a==='exam-prev'?Math.max(0,state.exam.index-1):a==='exam-next'?Math.min(24,state.exam.index+1):Number(el.dataset.index);confirmExam=false;render();break;
 case'finish-exam':saveExamInput();if(Object.values(state.exam.answers).filter(a=>String(a).trim()).length<25){confirmExam=true;render();}else submitExam();break;
 case'confirm-exam':submitExam();break;
 case'cancel-finish':confirmExam=false;render();break;
 case'exam-remedy':beginQuiz('errors',[similarQuestion(state.exam.questions[Number(el.dataset.index)])]);break;
 case'new-exam':state.exam=null;render();break;
 case'complete-review':mark('repaso');render();toast('Repaso completado. Revisa las reglas y los errores que queden pendientes.');break;
 case'print':window.print();break;
 case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='mi-progreso-informatica.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}break;
 case'reset':state.showReset=true;render();$('.modal button')?.focus();break;
 case'cancel-reset':state.showReset=false;render();break;
 case'confirm-reset':state=fresh();render();break;
 }}
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.image-modal')?.remove();if(state.showReset&&e.key==='Escape'){state.showReset=false;render();}});
document.addEventListener('click',e=>{const route=e.target.closest('[data-route]');if(route){navigate(route.dataset.route);return;}const el=e.target.closest('[data-action]');if(el&&!el.disabled)handleAction(el);});
document.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);switch(e.target.id){case'answer-form':checkAnswer(activeQ().type==='num'?data.get('answer'):(state.quiz.remedial?state.quiz.remedyAnswer:state.quiz.answer));break;case'exam-answer-form':saveExamInput();$('#exam-answer-status').textContent='Respuesta guardada. Puedes cambiarla.';break;case'solver-form':try{const value=data.get('value').trim(),from=Number(data.get('from')),to=Number(data.get('to'));conversionSteps(value,from,to);if(from===to)throw Error('Elige bases distintas para practicar una conversión.');state.solver={value,from,to,steps:1};solverError='';}catch(err){solverError=err.message;}render();break;case'sum-form':try{const values=data.get('values').split('+').map(x=>x.trim());if(values.length<2||values.length>3||values.some(v=>v.length>16))throw Error('Escribe dos o tres sumandos binarios, de hasta 16 bits cada uno.');const r=sumSteps(values);$('#sum-result').innerHTML=`<div class="solver-answer">${r.out}₂</div><ol class="step-list">${r.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`;}catch(err){$('#sum-result').innerHTML=`<p class="error-text" role="alert">${esc(err.message)}</p>`;}break;case'ascii-form':{const text=data.get('ascii');if(![...text].every(c=>c.charCodeAt(0)>=32&&c.charCodeAt(0)<=126)){asciiResult='<p class="error-text">Usa los caracteres 32–126 del ASCII original para este ejercicio.</p>';}else{asciiResult=`<p><strong>Texto:</strong> ${esc(text)}</p><p><strong>Decimal:</strong> ${[...text].map(c=>c.charCodeAt(0)).join(' ')}</p><p><strong>Hexadecimal:</strong> ${[...text].map(c=>c.charCodeAt(0).toString(16).toUpperCase()).join(' ')}</p>`;}$('#ascii-output').innerHTML=asciiResult;}break;}});
document.addEventListener('input',e=>{if(e.target.id==='answer'&&state.route==='simulacro'&&state.exam&&!state.exam.submitted)saveExamInput();else if(e.target.id==='answer'&&state.quiz){if(state.quiz.remedial)state.quiz.remedyAnswer=e.target.value;else state.quiz.answer=e.target.value;save();}});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(['inicio','diagnostico','fundamentos','procedimientos','tarjetas','simulacro','repaso','fuentes'].includes(r))navigate(r);});
window.addEventListener('beforeunload',()=>{tick();saveExamInput();save();});
function tick(){const now=Date.now();if(state.running){const delta=Math.max(0,(now-state.lastTick)/1000);state.elapsed=Math.min(7200,state.elapsed+delta);if(state.exam&&!state.exam.submitted){state.exam.remaining=Math.max(0,state.exam.remaining-delta);if(state.exam.remaining===0){state.lastTick=now;submitExam();toast('Tiempo del simulacro terminado. Se calificaron las respuestas guardadas.');}}if(state.elapsed>=7200){state.running=false;if(state.exam&&!state.exam.submitted)submitExam();}}state.lastTick=now;save();const global=$('#global-study-time');if(global)global.textContent=formatTime(7200-state.elapsed);const gb=$('#global-toggle');if(gb){gb.textContent=state.running?'Ⅱ':'▶';gb.setAttribute('aria-label',(state.running?'Pausar':'Reanudar')+' sesión');}const el=$('#study-time');if(el)el.textContent=formatTime(7200-state.elapsed);const ex=$('#exam-time');if(ex)ex.textContent=formatTime(state.exam?.remaining||0);const p=$('#time-progress');if(p)p.style.width=state.elapsed/72+'%';const status=$('#clock-status');if(status)status.textContent=state.elapsed>=7200?'Sesión de 120 min terminada':state.running?'Sesión en marcha':'A tu ritmo · en pausa';const btn=$('#clock-toggle');if(btn){btn.textContent=state.running?'Ⅱ':'▶';btn.setAttribute('aria-label',(state.running?'Pausar':'Reanudar')+' cronómetro');}}
tick();render();setInterval(tick,1000);
